import hashlib
from pathlib import Path

paths = {
    'terms': Path('products/services/payment-handoff/terms-welfare-followon-v1.md'),
    'notice': Path('products/services/welfare-tender/followon-rehearsal/official-notice-refresh.json'),
    'contract': Path('docs/AGENTMAIL.md'),
}
expected = {
    'terms': '8da570ec00daaead3172576d80a5dfd535b0f6c4496ec6c15d0f154d5ff1f64a',
    'notice': 'a4d2af226911f6eb8a9c1c9b618276c5ccd471bbab6ce05b8a0df6165f1c24a2',
}
for label, path in paths.items():
    data = path.read_bytes()
